from pathlib import Path
import json,hashlib,collections,copy,datetime
R=Path('/home/ollie/Documents/sound'); P=R/'analysis/ableton-live-12.4.3/full-spec-v1/family-route-ledger-census-v1'
def J(p): return json.loads(p.read_bytes())
def H(b):return hashlib.sha256(b).hexdigest()
m=J(P/'manifest.json');assert (len((P/'manifest.json').read_bytes()),H((P/'manifest.json').read_bytes()))==(2354,'0cd252b1bd23bf9defc2620f12196991265c32c1fbacc70f76b73c0ab0807294')
assert {p.name for p in P.iterdir()}=={f['path'] for f in m['files']}|{'manifest.json'}
for f in m['files']:
 b=(P/f['path']).read_bytes();assert (len(b),H(b))==(f['bytes'],f['sha256'])
assert len(m['files'])==9 and sum(f['bytes'] for f in m['files'])==2268127
# Explicit independently selected required-unit schemas; no first-array fallback.
arrays={**dict.fromkeys(['mix','playback','transport','midi-note','structure-als','warp','mixer','corpus','tension','synthesis-instruments'],'outcomes'),**dict.fromkeys(['clip-launch','automation','electric','analog','collision','midi-user','bundled-parameters','browser-index','plugin-discovery','utility','arrangement','native-midi-effects','recording-comping'],'rows'),**dict.fromkeys(['dynamics','audio-video-export','sample-instruments'],'predicates'),**dict.fromkeys(['distortion','device-racks'],'bundles'),**dict.fromkeys(['delay-reverb','modulation-pitch-loop','legacy-native'],'required_outcomes'),'filter-eq':'clauses'}
translate={'X':'X','X-route':'X','S':'S','S-route':'S','S-retained-file-only':'S','none':'none','no-established-route':'none'}
def route(v):
 assert v in translate;return translate[v]
def counted(rows):return dict(collections.Counter(route(v) for v in rows))
proof=J(P/'census.json'); selected=J(P/'selection.json')['families'];assert len(arrays)==len(selected)==32
rawunits=[json.loads(x) for x in (P/'required-units.jsonl').read_text().splitlines()];actualunits=collections.defaultdict(list)
for u in rawunits:actualunits[u['family']].append(u)
assert set(arrays)==set(actualunits)=={x['family'] for x in selected}
results=[];allroutes=[];documentary=collections.Counter();route_spellings=collections.Counter()
for e in selected:
 family=e['family'];assert arrays[family]==e['required_array'];path=R/e['directory'];ledger=J(path/'route-ledger.json');source=ledger
 if family=='analog':
  source=J(R/ledger['base_ledger']['path']);assert len(ledger['row_updates'])==10
  for update in ledger['row_updates']:assert set(update['set'])<=set(ledger['allowed_changed_row_fields']) and not set(update['set'])&{'route','id','requirement','observable_predicate'}
 rows=source[arrays[family]];assert len(rows)==len(actualunits[family]);observed=[]
 for n,(row,u) in enumerate(zip(rows,actualunits[family])):
  assert row['id']==u['id'] and u['required_pointer']==f'/{arrays[family]}/{n}'
  if arrays[family]=='predicates':
   candidates=[(i,c) for i,c in enumerate(source['contexts']) if c['predicate_id']==row['id']]
   required=[(i,c) for i,c in candidates if c['route']!='no-established-exact-target-route'];assert len(required)==1
   i,c=required[0]
   if family=='sample-instruments':assert c['source_annotation_not_extra_outcome'] is False
   else:assert c['record_kind']=='required-observable-context'
   ignored=[c for i,c in candidates if c['route']=='no-established-exact-target-route'];assert len(ignored)<=1
   for c2 in ignored:
    assert c2.get('source_annotation_not_extra_outcome') is True if family=='sample-instruments' else c2['record_kind']=='source-evidence-annotation'
   documentary[family]+=len(ignored);v=c['route'];ptr=f'/contexts/{i}/route'
  else:
   key='route_class' if family=='recording-comping' else 'route';v=row[key];ptr=f'/{arrays[family]}/{n}/{key}'
  assert u['route_pointer']==ptr and u['raw_route']==v and u['route']==route(v)
  observed.append(v);route_spellings[v]+=1
 counts={k:counted(observed).get(k,0) for k in ['X','S','none']};f=next(x for x in proof['families'] if x['family']==family);assert counts==f['counts']
 results.append(dict(family=family,required_array=arrays[family],units=len(rows),counts=counts));allroutes+=observed
assert len(allroutes)==5624 and counted(allroutes)=={'X':691,'S':1076,'none':3857}
assert documentary=={'dynamics':142,'audio-video-export':46,'sample-instruments':221}
assert len(set((u['family'],u['id']) for u in rawunits))==5624
expected_order=sorted(results,key=lambda x:(-x['counts']['X'],x['family']));assert [x['family'] for x in proof['priority_proposal']]==[x['family'] for x in expected_order]
assert sum(x['counts']['X']==0 for x in results)==16
# Independent finite controls of required-route handling and scope distinctions.
controls=[]
for bad in [None,'U','S-retained-fixture-only','no-established-exact-target-route','X?']:
 try:route(bad)
 except AssertionError:controls.append(repr(bad))
 else:raise AssertionError('Accepted invalid route')
assert counted(['X-route','S-retained-file-only','none'])=={'X':1,'S':1,'none':1}
assert sum(x['counts']['X'] for x in results if x['family']!='analog')==492
assert sum(x['counts']['S'] for x in results if x['family']!='analog')==1046
assert sum(x['counts']['none'] for x in results if x['family']!='analog')==3845
# Custody for the 68 exact selected immutable docs; mutable snapshots are as-of evidence.
pins=J(P/'source-pins.json')['pins'];immutable=[x for x in pins if x['kind']=='immutable'];assert len(immutable)==68
for pin in immutable:
 b=(R/pin['path']).read_bytes();assert (len(b),H(b))==(pin['bytes'],pin['sha256'])
